package sframe

// Every case in vectors/sframe. rfc9605.json is RFC 9605 Appendix C; the rest
// are generated by the Swift implementation.

import (
	"bytes"
	"crypto/hkdf"
	"encoding/hex"
	"encoding/json"
	"os"
	"path/filepath"
	"slices"
	"testing"
)

const vectorDirectory = "../../vectors/sframe"

func load[Case any](t *testing.T, name string) []Case {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(vectorDirectory, name))
	if err != nil {
		t.Fatal(err)
	}
	var file struct {
		Library string `json:"library"`
		Cases   []Case `json:"cases"`
	}
	if err := json.Unmarshal(data, &file); err != nil {
		t.Fatalf("%s: %v", name, err)
	}
	if file.Library != "moqom-sframe" || len(file.Cases) == 0 {
		t.Fatalf("%s: library %q, %d cases", name, file.Library, len(file.Cases))
	}
	return file.Cases
}

func unhex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatal(err)
	}
	return b
}

type metadataVector struct {
	Track struct {
		NamespaceHex []string `json:"namespace_hex"`
		NameHex      string   `json:"name_hex"`
	} `json:"track"`
	Group      uint64 `json:"group"`
	Object     uint64 `json:"object"`
	Priority   uint8  `json:"priority"`
	Properties []struct {
		Type     uint64  `json:"type"`
		Integer  *uint64 `json:"integer"`
		BytesHex *string `json:"bytes_hex"`
	} `json:"properties"`
}

func (v metadataVector) metadata(t *testing.T) Metadata {
	m := Metadata{Track: Track{Name: unhex(t, v.Track.NameHex)}, Group: v.Group, Object: v.Object, Priority: v.Priority}
	for _, field := range v.Track.NamespaceHex {
		m.Track.Namespace = append(m.Track.Namespace, unhex(t, field))
	}
	for _, p := range v.Properties {
		if p.Integer != nil {
			m.Properties = append(m.Properties, IntegerProperty(p.Type, *p.Integer))
		} else {
			m.Properties = append(m.Properties, BytesProperty(p.Type, unhex(t, *p.BytesHex)))
		}
	}
	return m
}

// expect checks one outcome against a vector's pt_hex or error.
func expect(t *testing.T, name string, got []byte, err error, ptHex, class string) {
	t.Helper()
	if class != "" {
		if Class(err) != class {
			t.Errorf("%s: got %v, want %s", name, err, class)
		}
		return
	}
	if err != nil {
		t.Errorf("%s: %v", name, err)
	} else if hex.EncodeToString(got) != ptHex {
		t.Errorf("%s: plaintext %x, want %s", name, got, ptHex)
	}
}

func TestRFC9605(t *testing.T) {
	type rfcCase struct {
		Name               string `json:"name"`
		Kind               string `json:"kind"`
		Skip               string `json:"skip"`
		Kid                uint64 `json:"kid"`
		Ctr                uint64 `json:"ctr"`
		HeaderHex          string `json:"header_hex"`
		CipherSuite        uint16 `json:"cipher_suite"`
		BaseKeyHex         string `json:"base_key_hex"`
		SFrameKeyLabelHex  string `json:"sframe_key_label_hex"`
		SFrameSaltLabelHex string `json:"sframe_salt_label_hex"`
		SFrameSecretHex    string `json:"sframe_secret_hex"`
		SFrameKeyHex       string `json:"sframe_key_hex"`
		SFrameSaltHex      string `json:"sframe_salt_hex"`
		MetadataHex        string `json:"metadata_hex"`
		NonceHex           string `json:"nonce_hex"`
		AADHex             string `json:"aad_hex"`
		PTHex              string `json:"pt_hex"`
		CTHex              string `json:"ct_hex"`
	}
	var headers, sframes, skipped int
	for _, c := range load[rfcCase](t, "rfc9605.json") {
		switch {
		case c.Skip != "":
			skipped++
		case c.Kind == "header":
			headers++
			h := Header{KeyID: c.Kid, Counter: c.Ctr}
			if got := hex.EncodeToString(h.Encode()); got != c.HeaderHex {
				t.Errorf("%s: encoded %s", c.Name, got)
			}
			parsed, n, err := ReadHeader(unhex(t, c.HeaderHex))
			if err != nil || parsed != h || n != len(c.HeaderHex)/2 {
				t.Errorf("%s: parsed %+v %d %v", c.Name, parsed, n, err)
			}
		case c.Kind == "sframe":
			sframes++
			suite := CipherSuite(c.CipherSuite)
			if got := hex.EncodeToString(label("SFrame 1.0 Secret key ", c.Kid, suite)); got != c.SFrameKeyLabelHex {
				t.Errorf("%s: key label %s", c.Name, got)
			}
			if got := hex.EncodeToString(label("SFrame 1.0 Secret salt ", c.Kid, suite)); got != c.SFrameSaltLabelHex {
				t.Errorf("%s: salt label %s", c.Name, got)
			}
			secret, _ := hkdf.Extract(suite.hash(), unhex(t, c.BaseKeyHex), nil)
			if hex.EncodeToString(secret) != c.SFrameSecretHex {
				t.Errorf("%s: secret %x", c.Name, secret)
			}
			// Appendix C derives suite 0x0005 keys from a 16-byte base key,
			// which NewKey refuses.
			key, err := newKey(c.Kid, unhex(t, c.BaseKeyHex), suite)
			if err != nil {
				t.Fatal(err)
			}
			if hex.EncodeToString(key.key) != c.SFrameKeyHex || hex.EncodeToString(key.salt) != c.SFrameSaltHex {
				t.Errorf("%s: key %x salt %x", c.Name, key.key, key.salt)
			}
			if got := hex.EncodeToString(key.nonce(c.Ctr)); got != c.NonceHex {
				t.Errorf("%s: nonce %s", c.Name, got)
			}
			header := Header{KeyID: c.Kid, Counter: c.Ctr}.Encode()
			aad := append(slices.Clone(header), unhex(t, c.MetadataHex)...)
			if hex.EncodeToString(aad) != c.AADHex {
				t.Errorf("%s: aad %x", c.Name, aad)
			}
			if got := hex.EncodeToString(key.seal(header, unhex(t, c.PTHex), c.Ctr, aad)); got != c.CTHex {
				t.Errorf("%s: ct %s", c.Name, got)
			}
			r := NewReceiver(DefaultReplayWindow)
			r.Add(key)
			pt, err := r.UnprotectRaw(unhex(t, c.CTHex), unhex(t, c.MetadataHex))
			expect(t, c.Name, pt, err, c.PTHex, "")
		default:
			t.Errorf("%s: unexpected kind %s", c.Name, c.Kind)
		}
	}
	if headers != 289 || sframes != 1 || skipped != 7 {
		t.Errorf("ran %d headers, %d sframe, skipped %d", headers, sframes, skipped)
	}
}

func TestMetadataVectors(t *testing.T) {
	type metadataCase struct {
		Name       string         `json:"name"`
		Metadata   metadataVector `json:"metadata"`
		EncodedHex *string        `json:"encoded_hex"`
		Error      string         `json:"error"`
	}
	for _, c := range load[metadataCase](t, "metadata.json") {
		got, err := c.Metadata.metadata(t).Encode()
		if c.Error != "" {
			if Class(err) != c.Error {
				t.Errorf("%s: got %x %v, want %s", c.Name, got, err, c.Error)
			}
		} else if err != nil || hex.EncodeToString(got) != *c.EncodedHex {
			t.Errorf("%s: got %x %v", c.Name, got, err)
		}
	}
}

func TestKeyIDVectors(t *testing.T) {
	type kidCase struct {
		Name      string `json:"name"`
		Leaf      uint32 `json:"leaf"`
		Epoch     uint64 `json:"epoch"`
		Kid       uint64 `json:"kid"`
		EpochTag  uint64 `json:"epoch_tag"`
		HeaderHex string `json:"header_hex"`
	}
	for _, c := range load[kidCase](t, "kid.json") {
		if MLSKeyID(c.Leaf, c.Epoch) != c.Kid || EpochTag(c.Kid) != c.EpochTag {
			t.Errorf("%s: kid %x tag %d", c.Name, MLSKeyID(c.Leaf, c.Epoch), EpochTag(c.Kid))
		}
		if got := hex.EncodeToString(Header{KeyID: c.Kid}.Encode()); got != c.HeaderHex {
			t.Errorf("%s: header %s", c.Name, got)
		}
	}
}

func TestNonceVectors(t *testing.T) {
	type nonceCase struct {
		Name          string `json:"name"`
		CipherSuite   uint16 `json:"cipher_suite"`
		Kid           uint64 `json:"kid"`
		Ctr           uint64 `json:"ctr"`
		BaseKeyHex    string `json:"base_key_hex"`
		SFrameKeyHex  string `json:"sframe_key_hex"`
		SFrameSaltHex string `json:"sframe_salt_hex"`
		NonceHex      string `json:"nonce_hex"`
		HeaderHex     string `json:"header_hex"`
	}
	for _, c := range load[nonceCase](t, "nonce.json") {
		key, err := NewKey(c.Kid, unhex(t, c.BaseKeyHex), CipherSuite(c.CipherSuite))
		if err != nil {
			t.Fatal(err)
		}
		if hex.EncodeToString(key.key) != c.SFrameKeyHex || hex.EncodeToString(key.salt) != c.SFrameSaltHex {
			t.Errorf("%s: key %x salt %x", c.Name, key.key, key.salt)
		}
		if got := hex.EncodeToString(key.nonce(c.Ctr)); got != c.NonceHex {
			t.Errorf("%s: nonce %s", c.Name, got)
		}
		if got := hex.EncodeToString(Header{KeyID: c.Kid, Counter: c.Ctr}.Encode()); got != c.HeaderHex {
			t.Errorf("%s: header %s", c.Name, got)
		}
	}
}

func TestSealOpenVectors(t *testing.T) {
	type sealCase struct {
		Name        string         `json:"name"`
		CipherSuite uint16         `json:"cipher_suite"`
		Kid         uint64         `json:"kid"`
		BaseKeyHex  string         `json:"base_key_hex"`
		Metadata    metadataVector `json:"metadata"`
		Seals       []struct {
			PTHex     string `json:"pt_hex"`
			ObjectHex string `json:"object_hex"`
		} `json:"seals"`
	}
	for _, c := range load[sealCase](t, "seal-open.json") {
		sealer, err := NewContext(CipherSuite(c.CipherSuite), c.Kid, unhex(t, c.BaseKeyHex))
		if err != nil {
			t.Fatal(err)
		}
		opener, _ := NewContext(CipherSuite(c.CipherSuite), c.Kid, unhex(t, c.BaseKeyHex))
		metadata := c.Metadata.metadata(t)
		for i, s := range c.Seals {
			object, err := sealer.Seal(unhex(t, s.PTHex), metadata)
			if err != nil || !bytes.Equal(object, unhex(t, s.ObjectHex)) {
				t.Errorf("%s seal %d: %x %v", c.Name, i, object, err)
			}
			pt, err := opener.Open(unhex(t, s.ObjectHex), metadata)
			expect(t, c.Name, pt, err, s.PTHex, "")
		}
	}
}

func TestOpenVectors(t *testing.T) {
	type openCase struct {
		Name        string         `json:"name"`
		CipherSuite uint16         `json:"cipher_suite"`
		Kid         uint64         `json:"kid"`
		BaseKeyHex  string         `json:"base_key_hex"`
		Metadata    metadataVector `json:"metadata"`
		ObjectHex   string         `json:"object_hex"`
		PTHex       string         `json:"pt_hex"`
		Error       string         `json:"error"`
	}
	for _, c := range load[openCase](t, "open.json") {
		context, err := NewContext(CipherSuite(c.CipherSuite), c.Kid, unhex(t, c.BaseKeyHex))
		if err != nil {
			t.Fatal(err)
		}
		pt, err := context.Open(unhex(t, c.ObjectHex), c.Metadata.metadata(t))
		expect(t, c.Name, pt, err, c.PTHex, c.Error)
	}
}

func TestReplayVectors(t *testing.T) {
	type replayCase struct {
		Name         string         `json:"name"`
		CipherSuite  uint16         `json:"cipher_suite"`
		Kid          uint64         `json:"kid"`
		BaseKeyHex   string         `json:"base_key_hex"`
		ReplayWindow uint64         `json:"replay_window"`
		Metadata     metadataVector `json:"metadata"`
		Steps        []struct {
			ObjectHex string `json:"object_hex"`
			PTHex     string `json:"pt_hex"`
			Error     string `json:"error"`
		} `json:"steps"`
	}
	for _, c := range load[replayCase](t, "replay.json") {
		context, err := NewContextWindow(CipherSuite(c.CipherSuite), c.Kid, unhex(t, c.BaseKeyHex), c.ReplayWindow)
		if err != nil {
			t.Fatal(err)
		}
		metadata := c.Metadata.metadata(t)
		for _, s := range c.Steps {
			pt, err := context.Open(unhex(t, s.ObjectHex), metadata)
			expect(t, c.Name, pt, err, s.PTHex, s.Error)
		}
	}
}
